  Exercise(id:"python-c1-t5-project-4-v1", topic:"python-c1-t5", category:"Project", type:"code", title:"Conditionals: validated mock report", prompt:"Read a target label, total request count and failed count. The last two inputs are valid integer text but may have invalid values. Strip/lowercase the target. If target is empty, either count is negative, or failed exceeds total, output Invalid only. Otherwise output Target: NAME, Failure rate: P%, then Level: LABEL on three lines. Use 0.00% for a zero total. LABEL is Alert for at least 10 failed, Watch for 5 through 9, and Normal below 5. Include a function report(target, total, failed) that returns the complete report string; print its return value once in the script. No real scans or file parsing.", tests:[{"input":[" EXAMPLE.ORG ","20","3"],"expected":"Target: example.org\nFailure rate: 15.00%\nLevel: Normal","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":[" DEMO ","10","5"],"expected":"Target: demo\nFailure rate: 50.00%\nLevel: Watch","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","10","10"],"expected":"Target: mock\nFailure rate: 100.00%\nLevel: Alert","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","0","0"],"expected":"Target: mock\nFailure rate: 0.00%\nLevel: Normal","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["  ","5","1"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","5","6"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","-1","0"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"},{"input":["mock","5","-1"],"expected":"Invalid","harness":"assert callable(globals().get('report')), 'Define report(target, total, failed).'\nassert report(' MOCK ',0,0)=='Target: mock\\nFailure rate: 0.00%\\nLevel: Normal', 'Return the report string with the zero-total rule.'","comparison":"normalized"}], hints:["Plan invalid cases before the valid report."], required:false, filename:"main.py"),
